  function model(ctx) {
    if (!ctx.state.learning || typeof ctx.state.learning !== 'object') ctx.state.learning = {};
    const s = ctx.state.learning;
    if (!courses.some(c => c.id === s.selectedCourse)) s.selectedCourse='methods';
    if (!Number.isInteger(s.page) || s.page < 0 || s.page > 2) s.page=0;
    if (!Number.isInteger(s.topic) || s.topic < 0 || s.topic > 2) s.topic=0;
    if (!['plan','cards','quiz'].includes(s.reviewTab)) s.reviewTab='plan';
    if (!s.answers || typeof s.answers !== 'object') s.answers={};
    for (const key of ['replies','replyDrafts','tutorNotes','tutorDrafts','approvals']) if (!s[key] || typeof s[key] !== 'object') s[key]={};
    if (!Array.isArray(s.completedDays)) s.completedDays=[];
    return s;
  }
  function course(ctx) {return courses.find(c=>c.id===model(ctx).selectedCourse);}
